-- Existing generic EKB incidents are preserved and referenced, not duplicated.
DO $ekb$
DECLARE v_n int;
BEGIN
  INSERT INTO public.lf_error_knowledge
  (id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,estado,evidencia,source_ref,root_cause_family,frecuencia,primera_vez,ultima_vez,lote_origen,pr,lifecycle_phase,consumer_role,detectability,source_context,created_at,updated_at)
  VALUES (gen_random_uuid(),'IG-M92-TOOL-SAFETY-ATTRIBUTION-001','ENGINEERING_EXECUTION','Rechazo de OpenAI tool confundido con error de Supabase y retraso de inicio M9.2','Durante M9.2/PAULO-089 el bootstrap SQL fue rechazado por el control de seguridad local de la herramienta (mensaje ''Los controles de seguridad de OpenAI bloquearon esta llamada a la herramienta''). Inicialmente se atribuyo incorrectamente el bloqueo a Supabase. SELECT 1 y el bootstrap de alcance minimo pasaron, habilitando la unidad; otros rechazos iguales se recuperaron al reducir el lote.','Se confundio la capa de seguridad del conector/harness con errores retornados por PostgreSQL sin confirmar SQLSTATE ni resultado de servidor.','TOOL_GATEWAY_REJECTION_MISATTRIBUTED_TO_POSTGRES','Clasificar el origen con evidencia: error de herramienta OpenAI vs SQLSTATE/HttpException PostgreSQL vs GitHub. Secuencia acordada por el usuario: intento normal -> consulta minima -> reintento de la operacion exacta -> tras 10 segundos ultimo reintento; si persiste, registrar CONNECTOR_BLOCKED y analizar raiz, sin reiniciar la unidad ni declarar fallo de la base. No afirmar que esta politica ya esta automatizada.','PASS operativo M9.2: SELECT 1 y bootstrap canonico finalmente ejecutados; avance posterior 6/6 DONE. Verificar automatizacion transversal de la secuencia por separado; no declararla instalada.','HIGH','ACTIVO','supabase://mhwmirqcgxxukpctffuv/programacion.fn_engineering_unit_bootstrap_v3/M9.2; supabase://programacion.v_engineering_work_progress/PAULO-089','supabase://programacion.fn_engineering_unit_bootstrap_v3','R5_EROSION_PROCESO',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','M9.2 / PAULO-089','EXECUTION',ARRAY['INPUT_GOVERNANCE','ENGINEERING_SCHEDULER']::text[],'LOUD_EARLY','2026-10-09 M9.2 closure reviewed 2026-10-11',now(),now()),
(gen_random_uuid(),'IG-M92-MANIFEST-CONSTRAINT-001','INPUT_GOVERNANCE','Manifest de release IG rechazado por constraint lf_capability_version_registry_manifest_check1','Primera prueba transaccional M9.2 intento insertar un manifest sin las secciones obligatorias migration, usage y currentness. PostgreSQL devolvio SQLSTATE 23514 CHECK lf_capability_version_registry_manifest_check1. Se leyo pg_get_constraintdef, se completo el manifest y la prueba con rollback paso. La migracion exacta posterior se fusiono y aplico.','El manifiesto inicial se construyo sin derivar requisitos directamente del constraint vivo de version registry.','VERSION_MANIFEST_REQUIRED_KEYS_NOT_PREFLIGHTED','Antes de INSERT versionado, leer constraint de manifest del registro transversal y comparar llaves obligatorias; probar la migracion completa en subtransaccion reversible y exigir ausencia de residuos antes de Git PR y apply. No relajar constraint ni inventar registry paralelo.','PASS: manifest version 1.0.0 de INPUT_GOVERNANCE queda RELEASED, CURRENT apunta al mismo SHA d1f5947613ef7e6d74d8763e39da534f79d70d61a2eab65e4765579fa4028e44; PR #2135 merged; ledger 20261009191226.','HIGH','ACTIVO','github://cristhianlujan/claude-persona-lf-patch/pull/2135; supabase://public.lf_capability_current/INPUT_GOVERNANCE@1.0.0','supabase://public.lf_capability_version_registry','R2_NO_VE',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','M9.2 / PAULO-089','EXECUTION',ARRAY['INPUT_GOVERNANCE','ENGINEERING_SCHEDULER']::text[],'LOUD_EARLY','2026-10-09 M9.2 closure reviewed 2026-10-11',now(),now()),
(gen_random_uuid(),'IG-M92-NEGATIVE-REGEX-GUARD-001','ENGINEERING_VALIDATION','Regex doblemente escapada dejaba aceptar reescritura de funciones en test M9.2','En primer self-test del archivo switch_revert_sandbox.py la prueba adversarial fallo con FAIL_MALICIOUS_REWRITE_ACCEPTED (exit 1). Los patrones raw Python contenian doble escape de \b y \s; no reconocian CREATE OR REPLACE FUNCTION. Se corrigieron los literales y se repitio en host SentinelX con PASS exit 0.','Generacion de fuente Python embebida altero escapes regex y transformo un guard negativo en permisivo; el self-test adversarial lo detecto antes de merge.','DOUBLE_ESCAPED_REGEX_NEGATIVE_GUARD','Toda regla que prohíba mutacion debe validarse con caso positivo y casos adversariales reales contra el mismo codigo fuente Git. Fallar cerrado si un CREATE OR REPLACE FUNCTION, DROP FUNCTION o UPDATE directo al puntero es aceptado. Versionar el test y ejecutar SHA exacto mergeado antes de assertion receipt.','PASS: self-test adversarial en host_3d5ff6fb467d4e9e exit 0, blob Git 59381b2a7fceaf0bb2a30601c7b2fad09f5829b3; PR #2141 merged; M9.2 SWITCH_REVERT_SANDBOX DONE con assertion.','HIGH','ACTIVO','github://cristhianlujan/claude-persona-lf-patch/pull/2141; github://cristhianlujan/claude-persona-lf-patch@bf272865d14eaa4cbd440424f119508d6fa69e5a/sandbox/lf_contract_gate_test/engineering_checkpoints/m9_2/switch_revert_sandbox.py','github://cristhianlujan/claude-persona-lf-patch/sandbox/lf_contract_gate_test/engineering_checkpoints/m9_2/switch_revert_sandbox.py','R2_NO_VE',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','M9.2 / PAULO-089','EXECUTION',ARRAY['INPUT_GOVERNANCE','ENGINEERING_SCHEDULER']::text[],'LOUD_EARLY','2026-10-09 M9.2 closure reviewed 2026-10-11',now(),now()),
(gen_random_uuid(),'IG-M92-CUTOVER-REUSE-PRECEDENT-001','INPUT_GOVERNANCE','Release IG debe usar version registry y CURRENT transversal sin duplicar assets runtime','M9.2 cerro la integracion del release INPUT_GOVERNANCE 1.0.0 como handle de servicio existente, reutilizando lf_capability_registry, lf_capability_version_registry, lf_capability_current y fn_lf_capability_promote_v1. Decision vigente DEC-INPUT-GOV-M1.7-RELEASE-BINDING-001. Inventario runtime de dominio permanece en lf_activos; no se creo otro puntero ni se reescribieron funciones.','Riesgo arquitectonico: resolver CURRENT/CANDIDATE por reglas IG propias crearia dos autoridades y divergencia no reversible.','REUSE_TRANSVERSAL_CURRENT_NOT_IG_LOCAL_POINTER','Para M9.*/M10.* y futuros releases, validar ADR vigente y CAPABILITY_CUTOVER disponible; versionar sobre capacidad transversal existente, manteniendo el runtime y sus assets de dominio independientes. Un PASE marcado skipped solo es NOT_APPLICABLE si la fuente de confianza verifica que esta desactivado; exigir controles activos SUCCESS, no contar skipped como PASS.','PASS: M9.2 PAULO-089 DONE 100% 6/6, INPUT_GOVERNANCE CURRENT 1.0.0, PR #2135 merged. Esta evidencia no implica activar candidate ni produccion.','MEDIUM','ACTIVO','github://cristhianlujan/claude-persona-lf-patch/pull/2135; supabase://transversal.decision_log/DEC-INPUT-GOV-M1.7-RELEASE-BINDING-001; supabase://programacion.v_engineering_work_progress/PAULO-089','supabase://public.lf_capability_current','R5_EROSION_PROCESO',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','M9.2 / PAULO-089','EXECUTION',ARRAY['INPUT_GOVERNANCE','ENGINEERING_SCHEDULER']::text[],'LOUD_EARLY','2026-10-09 M9.2 closure reviewed 2026-10-11',now(),now()),
(gen_random_uuid(),'IG-M92-CANARY-ROLLBACK-READBACK-001','ENGINEERING_VALIDATION','Canario CURRENT 1.0.0 -> 1.0.1 -> 1.0.0 validado sin residuo','M9.2 ejecuto switch y revert via fn_lf_capability_promote_v1 dentro de subtransaccion reversible. El candidato 1.0.1 existio solo durante la prueba, se revirtio a 1.0.0 y el rollback dejo una sola version persistente, sin residuos ni previous_version alterado. El test Python exacto del PR #2141 paso exit 0, con readback de baseline.','Riesgo de declarar switch satisfactorio a partir de un puntero o test estructural sin demostrar reversibilidad y sin comparar estado final de DB.','CANARY_SWITCH_REVERT_WITH_ROLLBACK_NO_RESIDUE','Exigir caso positivo de cambio, caso negativo con SHA obsoleto cuando aplique, reversión a baseline, prueba ROLLBACK sin residuos, lectura de manifest SHA/previous_version, runner real ejecutado desde Git merged y assertion receipt antes de DONE. La fixture canary no es una release CANDIDATE durable.','PASS: switch/revert en sandbox y readback INPUT_GOVERNANCE CURRENT=1.0.0 sha=d1f5947613ef7e6d74d8763e39da534f79d70d61a2eab65e4765579fa4028e44, registered_versions=1, previous_version NULL; M9.2 checkpoint 5 y terminal DONE.','HIGH','ACTIVO','github://cristhianlujan/claude-persona-lf-patch/pull/2141; supabase://mhwmirqcgxxukpctffuv/public.lf_capability_current/INPUT_GOVERNANCE@1.0.0','supabase://public.lf_capability_current','R2_NO_VE',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','M9.2 / PAULO-089','EXECUTION',ARRAY['INPUT_GOVERNANCE','ENGINEERING_SCHEDULER']::text[],'LOUD_EARLY','2026-10-09 M9.2 closure reviewed 2026-10-11',now(),now())
  ON CONFLICT (codigo) DO NOTHING;
  SELECT count(*) INTO v_n FROM public.lf_error_knowledge WHERE codigo IN ('IG-M92-TOOL-SAFETY-ATTRIBUTION-001','IG-M92-MANIFEST-CONSTRAINT-001','IG-M92-NEGATIVE-REGEX-GUARD-001','IG-M92-CUTOVER-REUSE-PRECEDENT-001','IG-M92-CANARY-ROLLBACK-READBACK-001') AND source_context='2026-10-09 M9.2 closure reviewed 2026-10-11';
  IF v_n<>5 THEN RAISE EXCEPTION 'IG_M92_EKB_READBACK_INCOMPLETE:%',v_n; END IF;
  IF NOT EXISTS (SELECT 1 FROM programacion.v_engineering_work_progress WHERE work_code='PAULO-089' AND status='DONE' AND progress_pct=100 AND open_blockers=0) THEN
    RAISE EXCEPTION 'IG_M92_EKB_TERMINAL_AUTHORITY_NOT_DONE';
  END IF;
END $ekb$;
